import{c as a,Q as o,j as t,m as l}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Ollama — Local Inference","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/ollama.md","filePath":"configuration/ollama.md","lastUpdated":null}'),n={name:"configuration/ollama.md"};function r(i,e,s,c,d,h){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="ollama-—-local-inference" tabindex="-1">Ollama — Local Inference <a class="header-anchor" href="#ollama-—-local-inference" aria-label="Permalink to &quot;Ollama — Local Inference&quot;">​</a></h1><p>Keep inference on infrastructure you control.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Run Ollama (<a href="https://ollama.com" target="_blank" rel="noreferrer">ollama.com</a>) on your LAN or on the FinSight host itself (uncomment the <code>ollama</code> service in <code>docker-compose.yml</code>).</li><li>Pull a model the Copilot supports (e.g. <code>qwen2.5</code>, <code>llama3</code>) — the model list shown in Settings → Agent comes from Ollama’s <code>/api/tags</code>.</li><li>In <strong>Settings → Agent</strong>, choose <strong>Ollama</strong>, set the base URL (default <code>http://ollama:11434</code> when co-located, or <code>http://&lt;lan-ip&gt;:11434</code> otherwise), pick the model, and save.</li></ol><p>No API key is needed.</p><h2 id="what-stays-local" tabindex="-1">What stays local <a class="header-anchor" href="#what-stays-local" aria-label="Permalink to &quot;What stays local&quot;">​</a></h2><p>The same <code>FinancialContext</code> FinSight would send to a cloud provider is sent to your Ollama instance over your local network. No data leaves your LAN or machine. Auto-categorization sends only the merchant + amount of uncategorized rows, over the same local HTTP.</p><h2 id="verifying" tabindex="-1">Verifying <a class="header-anchor" href="#verifying" aria-label="Permalink to &quot;Verifying&quot;">​</a></h2><p>Ask the Copilot a simple grounded question (“How much did I spend on groceries last month?”). If streaming shows reasoning and a cited total, Ollama is wired. Check <code>docker compose logs -f finsight</code> and the Ollama logs for errors if not.</p><p>Tip: for the Copilot to be fast enough to be pleasant, prefer a quantized 7–8B model on a machine with enough RAM.</p><p>See also: <a href="/FinSight/getting-started/configuring-ai">Configuring AI</a>, <a href="/FinSight/copilot/privacy">Privacy</a>.</p>',11)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
